import Foundation

// Shader mẫu (X-Ray súng + Hologram nhân vật) dùng cho preset 3 và 4.
// Sinh tự động từ bản make-file v3 — dữ liệu đã giải nén, mã hoá base64.

struct MakeToolsBlob {
    let pid: Int64
    let size: Int
    let base64: String

    func bytes() throws -> Bytes {
        guard let d = Data(base64Encoded: base64, options: .ignoreUnknownCharacters), d.count == size else {
            throw MakeToolsError("Shader nhúng bị hỏng (pid \(pid)).")
        }
        return Bytes(d)
    }
}

